import React, { useState, useEffect, useRef, useMemo } from 'react'

const TypewriterText = ({ children, speed = 10, delay = 0 }) => {
  const [displayedText, setDisplayedText] = useState('')
  const [currentIndex, setCurrentIndex] = useState(0)
  const [started, setStarted] = useState(false)
  const [showCursor, setShowCursor] = useState(true)
  const [isVisible, setIsVisible] = useState(false)
  const [isComplete, setIsComplete] = useState(false)
  const ref = useRef(null)
  const rafRef = useRef(null)
  const timeRef = useRef(null)

  // Detect mobile for faster speed
  const isMobile = useMemo(() => {
    if (typeof window === 'undefined') return false
    return window.innerWidth < 768
  }, [])
  
  const adjustedSpeed = isMobile ? speed * 0.6 : speed

  // Memoize text conversion
  const text = useMemo(() => 
    typeof children === 'string' 
      ? children 
      : React.Children.toArray(children).join(''),
    [children]
  )

  // Intersection Observer - only animate when visible
  useEffect(() => {
    if (!ref.current) return

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true)
          observer.disconnect()
        }
      },
      { 
        threshold: 0.1,
        rootMargin: '50px'
      }
    )

    observer.observe(ref.current)

    return () => observer.disconnect()
  }, [])

  // Handle initial delay
  useEffect(() => {
    if (!isVisible) return

    if (!started && delay > 0) {
      timeRef.current = setTimeout(() => setStarted(true), delay)
      return () => clearTimeout(timeRef.current)
    } else {
      setStarted(true)
    }
  }, [delay, started, isVisible])

  // Typing animation with requestAnimationFrame
  useEffect(() => {
    if (!started || currentIndex > text.length) return

    if (currentIndex === text.length) {
      setIsComplete(true)
      return
    }

    let lastTime = performance.now()

    const animate = (currentTime) => {
      const elapsed = currentTime - lastTime

      if (elapsed >= adjustedSpeed) {
        setCurrentIndex(prevIndex => {
          const newIndex = prevIndex + 1
          setDisplayedText(text.substring(0, newIndex))
          return newIndex
        })
        lastTime = currentTime
      }

      if (currentIndex < text.length) {
        rafRef.current = requestAnimationFrame(animate)
      }
    }

    rafRef.current = requestAnimationFrame(animate)

    return () => {
      if (rafRef.current) {
        cancelAnimationFrame(rafRef.current)
      }
    }
  }, [currentIndex, adjustedSpeed, text, started])

  // Cursor blink - only when typing is complete
  useEffect(() => {
    if (!isComplete) return

    const cursorInterval = setInterval(() => {
      setShowCursor(prev => !prev)
    }, 530)

    return () => clearInterval(cursorInterval)
  }, [isComplete])

  return (
    <span 
      ref={ref} 
      style={{ 
        whiteSpace: 'pre-wrap',
        transform: 'translateZ(0)',
        willChange: 'contents'
      }}
    >
      {displayedText}
      <span 
        style={{ 
          opacity: showCursor ? 1 : 0,
          transition: 'opacity 0.1s',
          display: 'inline-block',
          transform: 'translateZ(0)'
        }}
      >
         █
      </span>
    </span>
  )
}

export default TypewriterText
